import{_ as s,C as i,c as n,o as r,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Schedule activities","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/schedule-activities.md","filePath":"master/sales/crm/pipeline/schedule-activities.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/pipeline/schedule-activities.md"};function d(c,t,h,g,u,p){const o=i("ImagePopup");return r(),n("div",null,[t[0]||(t[0]=e('<h1 id="schedule-activities" tabindex="-1">Schedule activities <a class="header-anchor" href="#schedule-activities" aria-label="Permalink to &quot;Schedule activities&quot;">​</a></h1><p>An activity is a planned task, such as a call or a meeting. You attach it to a lead or an opportunity, so nothing is forgotten. The My Activities page lists everything that is due, and lets you clear it quickly.</p><blockquote><p><strong>In simple words:</strong> An activity is a reminder to do something for a deal, like a phone call. It has a type, a date and an owner.</p></blockquote><p>For how activities work across Aureus, see <a href="./../../../getting-started/activities.html">Activities</a>. This page covers the CRM screens.</p><h2 id="schedule-an-activity" tabindex="-1">Schedule an activity <a class="header-anchor" href="#schedule-an-activity" aria-label="Permalink to &quot;Schedule an activity&quot;">​</a></h2><p>Example: you plan a demo for <strong>Annual ERP licence - Sharma Textiles</strong>.</p><p>There are four places to start.</p><ul><li>The <strong>Schedule Activity</strong> button on the <strong>Activities</strong> tab of an opportunity or lead.</li><li>The clock icon on a Kanban card or list row.</li><li>The <strong>Schedule Activity</strong> button on <code>CRM → Sales → My Activities</code>.</li><li>The <strong>+</strong> button on a column of the activity board.</li></ul><ol><li>Open the opportunity and click its <strong>Activities</strong> tab.</li><li>Click <strong>Schedule Activity</strong>.</li></ol>',9)),a(o,{src:"/images1/crm/schedule-activity-dialog.png",alt:"Schedule activity dialog filled with a Meeting, a due date and the summary Product demo for Sharma Textiles"}),t[1]||(t[1]=e('<ol start="3"><li>Fill in the dialog <strong>Schedule activity</strong>.</li></ol><ul><li><strong><em>Opportunity:</em></strong> The deal the task belongs to. Required. It shows when you click <strong>Schedule Activity</strong> on <strong>My Activities</strong>. It is hidden when you schedule from the <strong>Activities</strong> tab of a deal.</li><li><strong><em>Activity Type:</em></strong> The kind of task, such as a call or a meeting. Required. Choosing a type fills the due date, summary and assignee from the type.</li><li><strong><em>Due Date:</em></strong> The day the task is due. Required. The type sets a default date.</li><li><strong><em>Summary:</em></strong> A short title, up to 255 characters.</li><li><strong><em>Assigned To:</em></strong> The user who does the task. Required. The default is the type default user, or you.</li><li><strong><em>Note:</em></strong> More detail in a text editor.</li></ul><p><strong>Example:</strong> Opportunity <code>Annual ERP licence - Sharma Textiles</code>, Activity Type <code>Meeting</code>, Due Date next Monday, Summary <code>Product demo for Sharma Textiles</code>, Assigned To <code>ERP Admin</code>.</p><ol start="4"><li>Click <strong>Schedule</strong>. A notification <strong>Activity scheduled</strong> appears.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You need permission to edit the deal. Without it, a notification <strong>Not allowed</strong> appears.</p></div><p>Plans and types are set up in <code>CRM → Configuration → Activity Types</code> and <code>Activity Plans</code>. For plans, see <a href="./../../../getting-started/activities.html">Activities</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Write a clear <strong>Summary</strong>. You then know the purpose at a glance.</p></div><h2 id="activities-on-one-deal" tabindex="-1">Activities on one deal <a class="header-anchor" href="#activities-on-one-deal" aria-label="Permalink to &quot;Activities on one deal&quot;">​</a></h2><p>The <strong>Activities</strong> tab of an opportunity shows its tasks, with a count badge. It has the same columns as below, without the deal and customer. With no tasks it says <strong>No planned activities</strong>.</p><p>On a Kanban card, the clock button opens the same list. Its colour tells the state: red for overdue, orange for today, green for planned, grey for none.</p><h2 id="my-activities" tabindex="-1">My Activities <a class="header-anchor" href="#my-activities" aria-label="Permalink to &quot;My Activities&quot;">​</a></h2><p>Go to <code>CRM → Sales → My Activities</code>.</p><p>The page has <strong>List</strong>, <strong>Kanban</strong> and <strong>Graph</strong> layouts. The title is <strong>Activities</strong>.</p>',13)),a(o,{src:"/images1/crm/my-activities-list.png",alt:"My Activities list with the Today tab open and four activities due today"}),t[2]||(t[2]=e('<h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>My Activities</strong></td><td>Activities assigned to you. This is the default.</td></tr><tr><td><strong>Overdue</strong></td><td>Your activities past their due date.</td></tr><tr><td><strong>Today</strong></td><td>Your activities due today.</td></tr><tr><td><strong>Planned</strong></td><td>Your activities due later.</td></tr><tr><td><strong>All Users</strong></td><td>Activities for everyone.</td></tr></tbody></table><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong>Due Date:</strong> a badge with the date and a status line: <strong>Overdue</strong>, <strong>Today</strong> or <strong>Planned</strong>.</li><li><strong>Lead / Opportunity:</strong> the deal. Click it to open the deal.</li><li><strong>Customer:</strong> the customer of the deal. You can hide it.</li><li><strong>Activity Type:</strong> the kind of task.</li><li><strong>Summary:</strong> the title, cut at 50 characters.</li><li><strong>Assigned To:</strong> who does it.</li><li>Hidden by default: <strong>Stage</strong> and <strong>Created At</strong>.</li></ul><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li><strong>Search.</strong> Type to match the deal name or the summary.</li><li><strong>Filter.</strong> Use <strong>Due</strong> (<strong>Overdue</strong>, <strong>Today</strong>, <strong>Planned</strong>), or build rules on <strong>Activity Type</strong>, <strong>Assigned To</strong>, <strong>Summary</strong>, <strong>Due Date</strong> and <strong>Created At</strong>.</li><li><strong>Group by.</strong> <strong>Activity Type</strong>, <strong>Assigned To</strong> or <strong>Due Date</strong>.</li><li><strong>Export.</strong> Select rows and choose <strong>Export</strong>.</li></ul><h3 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h3><p>Each column is an activity type. Each card shows the summary, the deal, the customer, the due label, a done button and the assignee. A column header shows the overdue count. Drag a card to another column to change its type.</p><h2 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Email</strong></td><td>Opens a dialog with <strong>To</strong>, <strong>Subject</strong> and <strong>Message</strong>, then sends the email to the contact of the deal. Shown only when the deal has an email address.</td></tr><tr><td><strong>SMS</strong></td><td>Opens a dialog with <strong>Recipient</strong> and <strong>Message</strong>, then sends a text.</td></tr><tr><td><strong>Snooze 7d</strong></td><td>Moves the due date seven days ahead. It counts from today, or from the current date when that is still ahead. A notification shows the new date.</td></tr><tr><td><strong>Mark as Done</strong> (check icon)</td><td>Asks for optional <strong>Feedback</strong>, then clears the task and logs it on the deal. A notification <strong>Activity done</strong> appears.</td></tr><tr><td><strong>Open Record</strong></td><td>Opens the deal. In the row menu.</td></tr><tr><td><strong>Reschedule</strong></td><td>Changes <strong>Due Date</strong>, <strong>Summary</strong> and <strong>Assigned To</strong>. In the row menu.</td></tr><tr><td><strong>Cancel Activity</strong></td><td>Removes the task. In the row menu.</td></tr></tbody></table><p>Bulk actions are <strong>Mark as Done</strong>, <strong>Cancel Activities</strong> and <strong>Export</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Due status.</strong> The status is computed from the due date and today. It changes by itself each day.</li><li><strong>Done.</strong> A done task moves from the list to the history of the deal, with your feedback.</li><li><strong>Board indicator.</strong> The activity bar on the pipeline columns counts the state of each deal. See <a href="./manage-opportunities.html">Manage opportunities</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../../getting-started/activities.html">Activities</a></li><li><a href="./manage-opportunities.html">Manage opportunities</a></li><li><a href="./../reporting/">CRM reports</a></li><li><a href="./../acquire-leads/convert-lead.html">Convert a lead</a></li></ul>',15))])}const v=s(l,[["render",d]]);export{y as __pageData,v as default};
